//! Unique original appearance-proc name selection and writer judgment.
use std::collections::HashSet;
use crate::{tree::SourceFile,pat,pat_match,key_policy_control::Control};
#[cfg(feature="legacy-sem")]use crate::{incr,tree::Tree};
use crate::reactive_writer_policy::{member_writer,writer_call};
#[cfg(feature="legacy-sem")]
pub fn names_in_file(f:&SourceFile)->Vec<String>{names_in_file_using(f,&mut crate::key_policy_control::Compatibility,&mut crate::key_policy_control::Compatibility).expect("original look names")}
pub fn names_in_file_using<C:Control,T:Control<Error=C::Error>>(f:&SourceFile,keep:&mut C,temp:&mut T)->Result<Vec<String>,C::Error>{keep.checkpoint()?;crate::key_policy_control::reserve(temp,||f.text().len().checked_mul(64)?.checked_add(4096))?;let row=pat!(r"\bDECLARE_APPEARANCE_PROC\s*\(\s*/[\w/]+\s*,\s*(?:TYPE_PROC_REF\(\s*[/\w]+\s*,\s*(\w+)\s*\)|PROC_REF\(\s*(\w+)\s*\))");let mut out=Vec::new();for line in f.clean().lines(){keep.checkpoint()?;if !line.contains("DECLARE_APPEARANCE_PROC"){continue}for m in row.captures_iter(line){keep.checkpoint()?;crate::raw_tree_report::row(keep,&mut out)?;out.push(crate::raw_tree_report::own(keep,if m.matched(1){m.s(1)}else{m.s(2)})?);}}crate::key_policy_control::reserve(keep,||out.len().checked_mul(4*std::mem::size_of::<String>())?.checked_add(128))?;out.sort();out.dedup();keep.checkpoint()?;Ok(out)}
fn add<C:Control>(set:&mut HashSet<String>,name:&str,c:&mut C)->Result<(),C::Error>{c.checkpoint()?;if set.contains(name){return Ok(())}if C::CHECKED&&set.len()==set.capacity(){let target=set.capacity().checked_mul(2).map(|n|n.max(4)).ok_or_else(||c.overflow())?;let bound=target.checked_mul(4).ok_or_else(||c.overflow())?;crate::key_policy_control::reserve(c,||bound.checked_mul(std::mem::size_of::<String>())?.checked_add(4096))?;set.try_reserve(target-set.len()).map_err(|_|c.allocation_failed())?;if set.capacity()>bound{return Err(c.allocation_failed())}}set.insert(crate::raw_tree_report::own(c,name)?);Ok(())}
pub fn merge<'a,C:Control>(rows:impl IntoIterator<Item=&'a Vec<String>>,c:&mut C)->Result<HashSet<String>,C::Error>{let mut names=HashSet::new();add(&mut names,"appearance_overlays",c)?;for row in rows{for name in row{add(&mut names,name,c)?;}}c.checkpoint()?;Ok(names)}
pub fn judge_using<C:Control,T:Control<Error=C::Error>>(file:&SourceFile,names:&HashSet<String>,keep:&mut C,temp:&mut T)->Result<Vec<(&'static str,usize)>,C::Error>{keep.checkpoint()?;crate::key_policy_control::reserve(temp,||file.text().len().checked_mul(file.rel.len().checked_mul(4)?.checked_add(512)?)?.checked_add(4096))?;let appearance_write=pat_match!(r"\s*(?:src\s*\.\s*)?(?:icon_state|icon|overlays|underlays|color|alpha|layer|plane|transform|pixel_x|pixel_y|pixel_w|pixel_z)\s*(?:=(?!=)|\+=|-=|\|=)");let mut out=Vec::new();let clean=file.clean();for proc in crate::dm::dx::procs_in(file){keep.checkpoint()?;if !names.contains(&proc.name)||proc.path=="/atom"||proc.path=="/datum"{continue}let mut lines=Vec::new();crate::key_policy_control::reserve(temp,||proc.body_len.checked_mul(4*std::mem::size_of::<(usize,&str)>())?.checked_add(128))?;for k in 0..proc.body_len{keep.checkpoint()?;lines.push((proc.body_start+k,clean.line(proc.body_start+k)));}let found=crate::reactive_writer_policy::reactive_writes_lines_using(&proc,&lines,keep,temp)?;for number in found{keep.checkpoint()?;let text=lines.iter().find(|(n,_)|*n==number).map(|(_,t)|*t).unwrap_or("");if suppressed(text,appearance_write){continue}crate::raw_tree_report::row(keep,&mut out)?;out.push(("dx_appearance_side_effect",number));}}keep.checkpoint()?;Ok(out)}
fn suppressed(text:&str,appearance_write:&crate::pat::Pat)->bool{appearance_write.is_match(text)&&!writer_call().is_match(text)&&!member_writer().is_match(text)}
#[cfg(feature="legacy-sem")]
pub fn scan(tree:&Tree,files:&[&SourceFile])->Vec<(&'static str,String,usize)>{let _=tree;let names=merge(&incr::facts("sys-dx-look-names",files,names_in_file),&mut crate::key_policy_control::Compatibility).expect("original look names");let mut out=Vec::new();for file in files{let rows=judge_using(file,&names,&mut crate::key_policy_control::Compatibility,&mut crate::key_policy_control::Compatibility).expect("original appearance judge");out.extend(rows.into_iter().map(|(rule,line)|(rule,file.rel.clone(),line)));}out}
